<?php
 namespace Pterodactyl\Services\Dezerx\Overview; use Locale; use Throwable; use Pterodactyl\Models\Node; use Pterodactyl\Models\Server; use Pterodactyl\Services\Dezerx\Addons; use Pterodactyl\Services\Dezerx\DiscordBot\Art; use Illuminate\Support\Facades\DB; use Illuminate\Support\Facades\Cache; class Overview { public const RANGES = [ '1h' => [3600, Collector::MINUTE, 60], '6h' => [21600, Collector::MINUTE, 300], '24h' => [86400, Collector::MINUTE, 300], '7d' => [604800, Collector::HOUR, 3600], '30d' => [2592000, Collector::HOUR, 10800], '90d' => [7776000, Collector::HOUR, 43200], '180d' => [15552000, Collector::DAY, 86400], '1y' => [31536000, Collector::DAY, 172800], 'all' => [0, Collector::DAY, 86400], ]; private const LIFETIME_POINTS = 180; public const STALE_AFTER = 180; private const CACHE_SECONDS = 20; private const TOP = 10; private const MB = 1048576; public function data(string $range, array $nodeIds): array { $range = array_key_exists($range, self::RANGES) ? $range : '24h'; $snapshot = Cache::get(Collector::SNAPSHOT); $snapshot = is_array($snapshot) ? $snapshot : null; sort($nodeIds); $key = 'dzo:data:' . sha1($range . '|' . implode(',', $nodeIds) . '|' . ($snapshot['taken_at'] ?? 0)); return Cache::remember($key, self::CACHE_SECONDS, fn () => $this->build($range, $nodeIds, $snapshot)); } private function build(string $range, array $nodeIds, ?array $snapshot): array { $all = Node::query()->with('location:id,short')->orderBy('name') ->get(['id', 'name', 'location_id', 'memory', 'memory_overallocate', 'disk', 'disk_overallocate', 'maintenance_mode']); $selected = $nodeIds === [] ? $all : $all->whereIn('id', $nodeIds)->values(); $ids = $selected->pluck('id')->map(fn ($id) => (int) $id)->all(); $counts = $ids === [] ? collect() : Server::query() ->selectRaw("node_id, COUNT(*) AS total, SUM(status = 'suspended') AS suspended, SUM(status IN ('installing', 'install_failed', 'reinstall_failed')) AS installing, SUM(memory) AS memory, SUM(disk) AS disk") ->whereIn('node_id', $ids) ->groupBy('node_id') ->get() ->keyBy('node_id'); $nodes = $selected->map(fn (Node $node) => $this->node($node, $snapshot['nodes'][$node->id] ?? null, $counts->get($node->id)))->all(); $series = $this->series($range, $ids); return [ 'range' => $range, 'generated_at' => time(), 'snapshot_at' => $snapshot['taken_at'] ?? null, 'stale' => $snapshot === null || time() - (int) $snapshot['taken_at'] > self::STALE_AFTER, 'all_nodes' => $all->map(fn (Node $node) => ['id' => (int) $node->id, 'name' => $node->name, 'location' => $node->location?->short, 'country' => $this->country($node)])->all(), 'selected' => $nodeIds, 'totals' => $this->totals($nodes, $series), 'nodes' => $nodes, 'series' => $series, 'top' => $this->topServers($snapshot, $ids), ]; } private function node(Node $node, ?array $snap, $counts): array { $system = (array) ($snap['system'] ?? []); $online = (bool) ($snap['reachable'] ?? false); $states = (array) ($snap['states'] ?? []); return [ 'id' => (int) $node->id, 'name' => $node->name, 'location' => $node->location?->short, 'country' => $this->country($node), 'maintenance' => (bool) $node->maintenance_mode, 'status' => $snap === null ? 'unknown' : ($online ? 'online' : 'unreachable'), 'error' => $online ? null : ($snap['error'] ?? null), 'version' => $system['version'] ?? null, 'servers' => [ 'total' => (int) ($counts->total ?? 0), 'running' => $online ? (int) ($states['running'] ?? 0) : 0, 'starting' => $online ? (int) ($states['starting'] ?? 0) : 0, 'stopping' => $online ? (int) ($states['stopping'] ?? 0) : 0, 'offline' => $online ? (int) ($states['offline'] ?? 0) : 0, 'suspended' => (int) ($counts->suspended ?? 0), 'installing' => (int) ($counts->installing ?? 0), 'unknown' => $online ? 0 : (int) ($counts->total ?? 0), ], 'cpu' => [ 'cores' => $online ? round((float) ($snap['cpu'] ?? 0) / 100, 2) : null, 'threads' => ($system['threads'] ?? 0) > 0 ? (int) $system['threads'] : null, ], 'memory' => [ 'used' => $online ? (int) ($snap['memory'] ?? 0) : null, 'physical' => ($system['memory'] ?? 0) > 0 ? (int) $system['memory'] : null, 'allocated' => (int) ($counts->memory ?? 0) * self::MB, 'limit' => (int) $node->memory * self::MB, ], 'disk' => [ 'used' => $online ? (int) ($snap['disk'] ?? 0) : null, 'allocated' => (int) ($counts->disk ?? 0) * self::MB, 'limit' => (int) $node->disk * self::MB, ], 'network' => [ 'rx' => $online ? round((float) ($snap['rx_rate'] ?? 0), 1) : null, 'tx' => $online ? round((float) ($snap['tx_rate'] ?? 0), 1) : null, ], ]; } private function totals(array $nodes, array $series): array { $sum = fn (callable $value) => array_sum(array_map(fn (array $node) => (float) ($value($node) ?? 0), $nodes)); $online = array_values(array_filter($nodes, fn (array $node) => $node['status'] === 'online')); $sumOnline = fn (callable $value) => array_sum(array_map(fn (array $node) => (float) ($value($node) ?? 0), $online)); return [ 'nodes' => count($nodes), 'online' => count($online), 'servers' => array_map(fn (string $state) => (int) $sum(fn ($node) => $node['servers'][$state]), [ 'total' => 'total', 'running' => 'running', 'starting' => 'starting', 'stopping' => 'stopping', 'offline' => 'offline', 'suspended' => 'suspended', 'installing' => 'installing', 'unknown' => 'unknown', ]), 'cpu' => [ 'cores' => round($sumOnline(fn ($node) => $node['cpu']['cores']), 2), 'threads' => (int) $sumOnline(fn ($node) => $node['cpu']['threads']), ], 'memory' => [ 'used' => (int) $sumOnline(fn ($node) => $node['memory']['used']), 'physical' => (int) $sumOnline(fn ($node) => $node['memory']['physical']), 'allocated' => (int) $sum(fn ($node) => $node['memory']['allocated']), 'limit' => (int) $sum(fn ($node) => $node['memory']['limit']), ], 'disk' => [ 'used' => (int) $sumOnline(fn ($node) => $node['disk']['used']), 'allocated' => (int) $sum(fn ($node) => $node['disk']['allocated']), 'limit' => (int) $sum(fn ($node) => $node['disk']['limit']), ], 'network' => [ 'rx' => round($sumOnline(fn ($node) => $node['network']['rx']), 1), 'tx' => round($sumOnline(fn ($node) => $node['network']['tx']), 1), ], 'transfer' => ['rx' => $series['transfer']['rx'], 'tx' => $series['transfer']['tx']], ]; } private function series(string $range, array $ids): array { [$span, $resolution, $bucket] = $range === 'all' ? $this->lifetime($ids) : self::RANGES[$range]; $now = time(); $last = intdiv($now, $bucket); $first = $last - intdiv($span, $bucket) + 1; $empty = ['t' => [], 'cpu' => [], 'memory' => [], 'disk' => [], 'rx' => [], 'tx' => [], 'running' => [], 'reporting' => [], 'bucket' => $bucket, 'transfer' => ['rx' => 0, 'tx' => 0]]; $rows = $ids === [] ? collect() : DB::table(Collector::TABLE) ->selectRaw('b, SUM(cpu) AS cpu, SUM(memory) AS memory, SUM(disk) AS disk, SUM(rx) AS rx, SUM(tx) AS tx, SUM(running) AS running, COUNT(*) AS reporting') ->fromSub( DB::table(Collector::TABLE) ->selectRaw('node_id, FLOOR(taken_at / ?) AS b, SUM(cpu_sum) / SUM(samples) AS cpu, SUM(memory_sum) / SUM(samples) AS memory, SUM(disk_sum) / SUM(samples) AS disk, SUM(rx_bytes) AS rx, SUM(tx_bytes) AS tx, SUM(running_sum) / SUM(samples) AS running', [$bucket]) ->where('resolution', $resolution) ->where('taken_at', '>=', $first * $bucket) ->where('samples', '>', 0) ->whereIn('node_id', $ids) ->groupBy('node_id', 'b'), 'per_node', ) ->groupBy('b') ->get() ->keyBy('b'); $out = $empty; for ($b = $first; $b <= $last; ++$b) { $row = $rows->get($b); $start = $b * $bucket; $seconds = $b === $last ? max(60, min($bucket, $now - $start)) : $bucket; $out['t'][] = $start; $out['cpu'][] = $row === null ? null : round((float) $row->cpu / 100, 2); $out['memory'][] = $row === null ? null : (int) $row->memory; $out['disk'][] = $row === null ? null : (int) $row->disk; $out['rx'][] = $row === null ? null : round((float) $row->rx / $seconds, 1); $out['tx'][] = $row === null ? null : round((float) $row->tx / $seconds, 1); $out['running'][] = $row === null ? null : round((float) $row->running, 1); $out['reporting'][] = $row === null ? 0 : (int) $row->reporting; $out['transfer']['rx'] += $row === null ? 0 : (int) $row->rx; $out['transfer']['tx'] += $row === null ? 0 : (int) $row->tx; } return $out; } private function lifetime(array $ids): array { $first = $ids === [] ? null : DB::table(Collector::TABLE)->where('resolution', Collector::DAY)->whereIn('node_id', $ids)->min('taken_at'); $span = max(86400, time() - (int) ($first ?? time()) + 86400); $bucket = 86400 * max(1, (int) ceil($span / 86400 / self::LIFETIME_POINTS)); return [$span, Collector::DAY, $bucket]; } private function topServers(?array $snapshot, array $ids): array { $empty = ['overall' => [], 'cpu' => [], 'memory' => [], 'disk' => [], 'network' => []]; if ($snapshot === null) { return $empty; } $usage = (array) ($snapshot['servers'] ?? []); $candidates = []; foreach ($ids as $id) { foreach ((array) ($snapshot['nodes'][$id]['top'] ?? []) as $metric => $uuids) { foreach ((array) $uuids as $uuid) { if (isset($usage[$uuid])) { $candidates[$metric][$uuid] = true; } } } } $score = [ 'cpu' => fn (array $u) => $u['cpu'], 'memory' => fn (array $u) => $u['memory'], 'disk' => fn (array $u) => $u['disk'], 'network' => fn (array $u) => $u['rx_rate'] + $u['tx_rate'], ]; $picked = []; foreach ($score as $metric => $value) { $uuids = array_keys($candidates[$metric] ?? []); usort($uuids, fn (string $a, string $b) => $value($usage[$b]) <=> $value($usage[$a])); $picked[$metric] = array_slice($uuids, 0, self::TOP); } $pool = array_map('strval', array_keys(array_merge([], ...array_values($candidates)))); $max = array_fill_keys(array_keys($score), 0); foreach ($pool as $uuid) { foreach ($score as $metric => $value) { $max[$metric] = max($max[$metric], $value($usage[$uuid])); } } $overall = fn (string $uuid) => array_sum(array_map( fn (string $metric) => $max[$metric] > 0 ? $score[$metric]($usage[$uuid]) / $max[$metric] : 0, array_keys($score), )); usort($pool, fn (string $a, string $b) => $overall($b) <=> $overall($a)); $picked = ['overall' => array_slice($pool, 0, self::TOP)] + $picked; $all = array_values(array_unique(array_merge(...array_values($picked)))); if ($all === []) { return $empty; } $servers = Server::query() ->with(['user:id,username', 'node:id,name,location_id', 'node.location:id,short', 'egg:id,uuid,name']) ->whereIn('uuid', $all) ->get(['id', 'uuid', 'uuidShort', 'name', 'owner_id', 'node_id', 'egg_id', 'memory', 'disk', 'cpu']) ->keyBy('uuid'); $out = $empty; foreach ($picked as $metric => $uuids) { foreach ($uuids as $uuid) { $server = $servers->get($uuid); if ($server === null) { continue; } $u = $usage[$uuid]; $out[$metric][] = [ 'id' => (int) $server->id, 'identifier' => $server->uuidShort, 'name' => $server->name, 'node' => $server->node?->name, 'node_country' => $server->node === null ? null : $this->country($server->node), 'logo' => Art::logo($server->egg?->uuid, $server->egg?->name), 'owner' => $server->user?->username, 'state' => $u['state'], 'cpu' => round((float) $u['cpu'], 1), 'cpu_limit' => (int) $server->cpu, 'memory' => (int) $u['memory'], 'memory_limit' => (int) $server->memory * self::MB, 'disk' => (int) $u['disk'], 'disk_limit' => (int) $server->disk * self::MB, 'rx' => round((float) $u['rx_rate'], 1), 'tx' => round((float) $u['tx_rate'], 1), ]; } } return $out; } private function country(Node $node): ?string { static $known = []; if (array_key_exists($node->id, $known)) { return $known[$node->id]; } return $known[$node->id] = self::flagFor($node->location?->short, $node->name); } public static function flagFor(?string ...$names): ?string { foreach ($names as $name) { $name = trim((string) $name); if ($name === '') { continue; } $candidates = [self::countries()[mb_strtolower($name)] ?? null]; if (preg_match('/^([A-Za-z]{2})(?=[-_ .\d]|$)/', $name, $match) === 1) { array_unshift($candidates, $match[1]); } foreach (array_filter($candidates) as $code) { $code = strtoupper($code); if (is_file(public_path('dezerx/flags/' . $code . '.svg'))) { return $code; } } } return null; } public static function glance(iterable $nodes): array { $snapshot = Cache::get(Collector::SNAPSHOT); if (!(Addons::get(Addons::ADMIN_OVERVIEW)['enabled'] ?? false) || !is_array($snapshot) || time() - (int) ($snapshot['taken_at'] ?? 0) > self::STALE_AFTER) { return []; } $ids = []; foreach ($nodes as $node) { $ids[] = (int) $node->id; } if ($ids === []) { return []; } $first = intdiv(time(), 3600) * 3600 - 23 * 3600; $hours = []; $rows = DB::table(Collector::TABLE) ->where('resolution', Collector::HOUR) ->whereIn('node_id', $ids) ->where('taken_at', '>=', $first) ->where('samples', '>', 0) ->get(['node_id', 'taken_at', 'samples', 'memory_sum']); foreach ($rows as $row) { $hours[(int) $row->node_id][intdiv((int) $row->taken_at - $first, 3600)] = $row->memory_sum / $row->samples; } $out = []; foreach ($ids as $id) { $snap = $snapshot['nodes'][$id] ?? null; if (!is_array($snap)) { $out[$id] = ['status' => 'unknown']; continue; } if (!($snap['reachable'] ?? false)) { $out[$id] = ['status' => 'unreachable', 'error' => (string) ($snap['error'] ?? '')]; continue; } $system = is_array($snap['system'] ?? null) ? $snap['system'] : []; $threads = (int) ($system['threads'] ?? 0); $physical = (int) ($system['memory'] ?? 0); $out[$id] = [ 'status' => 'online', 'running' => (int) ($snap['states']['running'] ?? 0), 'cpu' => $threads > 0 ? round((float) ($snap['cpu'] ?? 0) / $threads, 1) : null, 'memory' => self::bytes((int) ($snap['memory'] ?? 0)), 'physical' => $physical > 0 ? self::bytes($physical) : null, 'trend' => self::sparkline($hours[$id] ?? []), ]; } return $out; } private static function sparkline(array $values): ?array { if (count($values) < 2) { return null; } ksort($values); $peak = max($values); $points = []; foreach ($values as $hour => $value) { $y = $peak > 0 ? 17 - ($value / $peak) * 15 : 17; $points[] = round($hour * 72 / 23, 1) . ',' . round($y, 1); } $line = implode(' ', $points); $from = round(array_key_first($values) * 72 / 23, 1); $to = round(array_key_last($values) * 72 / 23, 1); return ['points' => $line, 'area' => "{$from},18 {$line} {$to},18", 'peak' => self::bytes((int) $peak)]; } private static function bytes(int $bytes): string { $gib = $bytes / (1024 * self::MB); if ($gib >= 1) { return ($gib >= 100 ? round($gib) : ($gib >= 10 ? round($gib, 1) : round($gib, 2))) . ' GiB'; } $mib = $bytes / self::MB; return ($mib >= 100 ? round($mib) : ($mib >= 10 ? round($mib, 1) : round($mib, 2))) . ' MiB'; } private static function countries(): array { if (!class_exists(Locale::class)) { return []; } try { return Cache::remember('dzo:countries', 86400, function () { $map = []; foreach (range('A', 'Z') as $a) { foreach (range('A', 'Z') as $b) { $name = Locale::getDisplayRegion('-' . $a . $b, 'en'); if (is_string($name) && $name !== '' && $name !== $a . $b) { $map[mb_strtolower($name)] = $a . $b; } } } return $map; }); } catch (Throwable) { return []; } } } 